CREATE TABLE IF NOT EXISTS __2048_write_fence (id INTEGER PRIMARY KEY CHECK (id = 1), phase TEXT NOT NULL CHECK (phase IN ('normal','drain','frozen')), epoch INTEGER NOT NULL DEFAULT 0, changed_at INTEGER NOT NULL DEFAULT 0);
INSERT INTO __2048_write_fence(id,phase) VALUES (1,'normal') ON CONFLICT(id) DO NOTHING;
CREATE TRIGGER IF NOT EXISTS __2048_fence_users_insert BEFORE INSERT ON users WHEN COALESCE((SELECT phase FROM __2048_write_fence WHERE id = 1), 'frozen') = 'frozen' BEGIN SELECT RAISE(ABORT, '2048_MIGRATION_FROZEN'); END;
